styleText:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --bg:         #F7F7F4;
      --white:      #FFFFFF;
      --accent:     #CDB18B;
      --accent-dim: #F2E4CF;
      --dark:       #0D1117;
      --dark-2:     #1A1F2E;
      --dark-3:     #0F1520;
      --text:       #111111;
      --muted:      #6B7280;
      --muted-2:    #9CA3AF;
      --border:     rgba(0,0,0,0.07);
      --border-2:   rgba(0,0,0,0.12);
      --shadow-xs:  0 1px 3px rgba(0,0,0,0.05);
      --shadow-sm:  0 2px 10px rgba(0,0,0,0.06);
      --shadow-md:  0 8px 32px rgba(0,0,0,0.08);
      --shadow-lg:  0 20px 60px rgba(0,0,0,0.10);
      --shadow-xl:  0 40px 100px rgba(0,0,0,0.12);
      --radius-sm:  10px;
      --radius-md:  16px;
      --radius-lg:  24px;
      --radius-xl:  32px;
      --radius-full:9999px;
    }
    html { scroll-behavior: smooth; }
    body { font-family: 'Inter', sans-serif; background: var(--bg); color: var(--text); line-height: 1.6; overflow-x: hidden; -webkit-font-smoothing: antialiased; }
    a { text-decoration: none; color: inherit; }

    @keyframes fadeInUp { from { opacity:0; transform:translateY(24px);} to { opacity:1; transform:translateY(0);} }
    @keyframes pulse-dot { 0%,100%{opacity:1;transform:scale(1);} 50%{opacity:.5;transform:scale(.85);} }
    .fade-in-up { animation: fadeInUp 0.7s cubic-bezier(.22,1,.36,1) both; }
    .d1{animation-delay:.1s;} .d2{animation-delay:.2s;} .d3{animation-delay:.3s;} .d4{animation-delay:.4s;}

    .container { width:100%; max-width:1200px; margin:0 auto; padding:0 32px; }
    .eyebrow { display:inline-flex;align-items:center;gap:7px;font-size:11px;font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);margin-bottom:18px; }
    .eyebrow-dot { width:6px;height:6px;border-radius:50%;background:var(--accent);animation:pulse-dot 2s ease infinite; }

    /* Buttons */
    .btn { display:inline-flex;align-items:center;gap:8px;border-radius:var(--radius-full);font-family:'Inter',sans-serif;font-weight:600;font-size:14px;cursor:pointer;transition:all .2s cubic-bezier(.22,1,.36,1);border:none;white-space:nowrap; }
    .btn-primary { background:var(--dark);color:#fff;padding:13px 28px;box-shadow:0 2px 8px rgba(0,0,0,.15); }
    .btn-primary:hover { background:var(--dark-2);transform:translateY(-2px);box-shadow:0 8px 24px rgba(0,0,0,.2); }
    .btn-accent  { background:var(--accent);color:var(--dark);padding:13px 28px;box-shadow:0 2px 8px rgba(205,177,139,.3); }
    .btn-accent:hover { background:#dac09e;transform:translateY(-2px);box-shadow:0 8px 24px rgba(205,177,139,.4); }
    .btn-outline { background:transparent;color:var(--text);padding:12px 24px;border:1.5px solid var(--border-2); }
    .btn-outline:hover { background:var(--white);color:#0D1117 !important;transform:translateY(-1px);box-shadow:var(--shadow-sm); }
    .btn-outline-light { background:transparent;color:rgba(255,255,255,.75);padding:12px 24px;border:1.5px solid rgba(255,255,255,.2); }
    .btn-outline-light:hover { background:rgba(255,255,255,.08); }

    /* ── Navbar ── */
    .navbar { position:fixed;top:0;left:0;right:0;z-index:1000;padding:0 40px;height:64px;display:flex;align-items:center;justify-content:space-between;background:rgba(247,247,244,.82);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);border-bottom:1px solid var(--border); }
    .nav-logo { display:flex;align-items:center;gap:9px;font-weight:800;font-size:18px;letter-spacing:-.03em; }
    .nav-logo-icon { width:30px;height:30px;background:var(--dark);border-radius:8px;display:flex;align-items:center;justify-content:center; }
    .nav-logo-icon svg { width:16px;height:16px; }
    .nav-links { display:flex;align-items:center;gap:2px;list-style:none; }
    .nav-links a { font-size:13px;font-weight:500;color:var(--muted);padding:7px 11px;border-radius:var(--radius-full);transition:all .15s;display:flex;align-items:center;gap:3px; }
    .nav-links a:hover,.nav-links a.active { color:var(--text);background:rgba(0,0,0,.04); }
    .nav-links a.active { color:var(--text);font-weight:600;background:rgba(0,0,0,.06); }
    .nav-actions { display:flex;align-items:center;gap:10px; }
    .nav-chevron { font-size:9px;opacity:.45; }
    .nav-item { position:relative;list-style:none; }
    .nav-item.has-mega:hover .nav-chevron,
    .nav-item.has-mega.mega-open .nav-chevron { transform:rotate(180deg);opacity:.7; }
    .mega-panel { position:fixed;top:64px;left:50%;transform:translateX(-50%) translateY(-6px);background:var(--white);border:1px solid var(--border-2);border-radius:var(--radius-lg);box-shadow:0 8px 16px rgba(0,0,0,.06),0 24px 64px rgba(0,0,0,.10);padding:24px;opacity:0;pointer-events:none;transition:opacity .18s ease,transform .18s ease;z-index:999; }
    .nav-item.has-mega:hover .mega-panel,
    .nav-item.has-mega.mega-open .mega-panel {
      opacity: 1;
      pointer-events: auto;
      transform: translateX(-50%) translateY(0);
    }
    .mega-products  { width:1040px; }
    .mega-solutions { width:680px; }
    .mega-platform  { width:680px; }
    /* Thin top accent bar */
    .mega-panel::before { content:'';position:absolute;top:0;left:24px;right:24px;height:2px;background:var(--accent);border-radius:0 0 2px 2px;opacity:.6; }
    /* Transparent hover bridge — prevents gap closing the menu */
    .mega-panel::after {
      content: '';
      position: absolute;
      top: -18px; left: 0; right: 0;
      height: 18px;
    }

    /* Hightouch-style column mega */
    .mega-cols { display:flex; align-items:flex-start; gap:0; }
    .mega-col {
      flex:1; padding:0 28px;
      border-right:1px solid var(--border-2);
      min-width:0;
    }
    .mega-col:first-child { padding-left:0; }
    .mega-col:last-child  { border-right:none; }

    .mega-col-label {
      font-size:10px; font-weight:700; letter-spacing:.1em;
      text-transform:uppercase; color:var(--muted);
      margin-bottom:16px; padding-bottom:12px;
      border-bottom:1px solid var(--border-2);
      white-space:nowrap;
    }
    .mega-col-link {
      display:block; font-size:14px; color:var(--text);
      text-decoration:none; padding:7px 0; font-weight:500;
      transition:color .15s; white-space:nowrap;
    }
    .mega-col-link:hover { color:var(--accent); }

    .mega-col-badge {
      font-size:9px; font-weight:700; letter-spacing:.05em;
      text-transform:uppercase; color:var(--accent);
      background:rgba(205,177,139,.15); border-radius:3px;
      padding:2px 5px; margin-left:6px; vertical-align:middle;
    }

    /* Featured column */
    .mega-col-featured { flex:0 0 200px !important; padding:0 0 0 28px !important; border-right:none !important; }
    .mega-featured-img {
      width:100%; height:110px; border-radius:var(--radius-sm);
      overflow:hidden; margin-bottom:12px;
    }
    .mega-featured-img img { width:100%; height:100%; object-fit:cover; }
    .mega-featured-desc {
      font-size:12.5px; color:var(--muted); line-height:1.65; margin-bottom:12px;
    }
    .mega-featured-link {
      font-size:12.5px; font-weight:600; color:var(--text);
      text-decoration:none; display:flex; align-items:center; gap:4px;
    }
    .mega-featured-link:hover { color:var(--accent); }

    /* ── Hero (same as pricing) ── */
    .contact-hero {
      background: url('/assets/Pricing Hero BG.webp') center/cover no-repeat;
      padding: 120px 0 120px;
      text-align: center;
      position: relative;
      overflow: hidden;
    }
    .contact-hero-bg { display:none; }
    .contact-hero .container { position:relative;z-index:1; }
    .contact-hero h1 {
      font-size:clamp(36px,5vw,64px);font-weight:900;line-height:1.04;letter-spacing:-.04em;
      color:var(--text);margin-bottom:20px;
    }
    .contact-hero h1 em { font-style:italic;font-family:'DM Serif Display',serif;font-weight:400;color:var(--text); } h2 em { font-style:italic; font-family:'DM Serif Display',serif; font-weight:400; } .section-headline em { font-style:italic; font-family:'DM Serif Display',serif; font-weight:400; }
    .contact-hero > .container > p { font-size:17px;color:var(--muted);max-width:500px;margin:0 auto 40px;line-height:1.75; }

    /* ── Contact Grid ── */
    .contact-grid {
      display: grid;
      grid-template-columns: 1fr 1.6fr;
      gap: 40px;
      align-items: start;
      text-align: left;
      margin-top: 0;
    }

    /* Left info panel */
    .contact-info-panel {
      background: var(--white);
      border-radius: 28px;
      padding: 36px 32px;
      border: 1px solid var(--border);
      box-shadow: none;
      height: 100%;
    }
    .contact-info-panel h3 {
      font-size: 20px;
      font-weight: 800;
      letter-spacing: -.025em;
      margin-bottom: 8px;
    }
    .contact-info-panel .sub {
      font-size: 13.5px;
      color: var(--muted);
      line-height: 1.65;
      margin-bottom: 36px;
    }
    .info-block { margin-bottom: 28px; }
    .info-block:last-of-type { margin-bottom: 0; }
    .info-label {
      font-size: 10px;
      font-weight: 700;
      letter-spacing: .1em;
      text-transform: uppercase;
      color: var(--muted-2);
      margin-bottom: 8px;
    }
    .info-value {
      font-size: 13.5px;
      color: var(--text);
      line-height: 1.75;
    }
    .info-value a { color: var(--text); transition: color .15s; }
    .info-value a:hover { color: var(--accent); }
    .info-socials { display:flex;gap:8px;margin-top:2px; }
    .info-social {
      width:32px;height:32px;border-radius:8px;
      background:var(--bg);border:1px solid var(--border-2);
      display:flex;align-items:center;justify-content:center;
      font-size:12px;cursor:pointer;transition:all .15s;
      color:var(--text);text-decoration:none;
    }
    .info-social:hover { background:var(--dark);color:#fff;border-color:var(--dark);transform:translateY(-2px); }
    .info-divider { height:1px;background:var(--border);margin:24px 0; }

    /* Right form card */
    .contact-form-card {
      background: var(--white);
      border-radius: 28px;
      padding: 36px 36px 40px;
      border: 1px solid var(--border);
    }
    .form-title { font-size:20px;font-weight:800;letter-spacing:-.025em;margin-bottom:6px; }
    .form-sub { font-size:13.5px;color:var(--muted);line-height:1.6;margin-bottom:28px; }
    .form-row { display:grid;grid-template-columns:1fr 1fr;gap:16px; }
    .form-group { margin-bottom:16px; min-width:0; }
    .form-group label { display:block;font-size:12px;font-weight:600;color:var(--muted);margin-bottom:6px;letter-spacing:.02em; }
    .form-group input,
    .form-group textarea,
    .form-group select {
      width:100%;font-family:'Inter',sans-serif;font-size:14px;color:var(--text);
      background:var(--bg);border:1.5px solid var(--border-2);
      border-radius:var(--radius-sm);padding:12px 14px;
      outline:none;transition:border-color .15s,box-shadow .15s;resize:none;
      appearance:none;-webkit-appearance:none;
    }
    /* Multi-select chip component */
    .ms-wrap { position:relative; min-width:0; }
    .ms-field {
      width:100%; height:46px; font-family:'Inter',sans-serif; font-size:14px; color:var(--text);
      background:var(--bg); border:1.5px solid var(--border-2);
      border-radius:var(--radius-sm); padding:0 36px 0 8px;
      outline:none; cursor:pointer; transition:border-color .15s, box-shadow .15s;
      display:flex; align-items:center; overflow:hidden; user-select:none;
    }
    .ms-chips-inner {
      display:flex; flex-wrap:nowrap; align-items:center; gap:5px;
      overflow-x:auto; overflow-y:hidden; scrollbar-width:none; min-width:0; flex:1;
      -webkit-mask-image:linear-gradient(to right, black calc(100% - 32px), transparent 100%);
      mask-image:linear-gradient(to right, black calc(100% - 32px), transparent 100%);
    }
    .ms-chips-inner::-webkit-scrollbar { display:none; }
    .ms-field.open, .ms-field:focus-within {
      border-color:var(--accent);
      box-shadow:0 0 0 3px rgba(205,177,139,.15);
      background:#fff;
    }
    .ms-placeholder { color:var(--muted-2); font-size:14px; padding:2px 4px; }
    .ms-chip {
      display:inline-flex; align-items:center; gap:4px;
      background:var(--accent-dim); border:1px solid rgba(205,177,139,.4);
      border-radius:var(--radius-full); padding:2px 8px 2px 10px;
      font-size:12px; font-weight:500; color:var(--dark); line-height:1.4;
      white-space:nowrap;
    }
    .ms-chip-x {
      display:inline-flex; align-items:center; justify-content:center;
      width:14px; height:14px; border-radius:50%;
      background:rgba(0,0,0,.12); color:var(--dark);
      font-size:10px; line-height:1; cursor:pointer; flex-shrink:0;
      transition:background .15s;
    }
    .ms-chip-x:hover { background:rgba(0,0,0,.25); }
    .ms-arrow {
      position:absolute; right:12px; top:50%; transform:translateY(-50%);
      pointer-events:none; transition:transform .2s; z-index:2;
    }
    .ms-wrap.open .ms-arrow { transform:translateY(-50%) rotate(180deg); }
    .ms-dropdown {
      position:absolute; top:calc(100% + 6px); left:0; right:0; z-index:200;
      background:#fff; border:1.5px solid var(--border-2);
      border-radius:var(--radius-sm); box-shadow:0 8px 32px rgba(0,0,0,.1);
      overflow:hidden; display:none; max-height:240px; overflow-y:auto;
    }
    .ms-wrap.open .ms-dropdown { display:block; }
    .ms-option {
      display:flex; align-items:center; gap:10px;
      padding:10px 14px; font-size:13.5px; color:var(--text);
      cursor:pointer; transition:background .12s;
    }
    .ms-option:hover { background:var(--bg); }
    .ms-option.selected { background:rgba(205,177,139,.08); }
    .ms-checkbox {
      width:16px; height:16px; border-radius:4px; flex-shrink:0;
      border:1.5px solid var(--border-2); background:#fff;
      display:flex; align-items:center; justify-content:center;
      transition:all .15s;
    }
    .ms-option.selected .ms-checkbox {
      background:var(--accent); border-color:var(--accent);
    }
    .ms-checkmark { display:none; }
    .ms-option.selected .ms-checkmark { display:block; }

    .form-group input:focus,
    .form-group textarea:focus {
      border-color:var(--accent);
      box-shadow:0 0 0 3px rgba(205,177,139,.15);
      background:#fff;
    }
    .form-group input::placeholder,
    .form-group textarea::placeholder { color:var(--muted-2); }
    .form-group textarea { height:100px; }
    .form-submit {
      width:100%;justify-content:center;font-size:15px;padding:16px 28px;
      border-radius:var(--radius-md);margin-top:4px;
      background:var(--accent);color:var(--dark);
      font-weight:700;cursor:pointer;border:none;
      font-family:'Inter',sans-serif;
      transition:all .2s cubic-bezier(.22,1,.36,1);
      box-shadow:0 2px 8px rgba(205,177,139,.3);
    }
    .form-submit:hover { background:#dac09e;transform:translateY(-2px);box-shadow:0 8px 24px rgba(205,177,139,.4); }

    /* ── Footer ── */
    .footer { background:var(--dark);color:rgba(255,255,255,.6);position:relative;overflow:hidden;padding-top:0; }
    .footer-bg { position:absolute;inset:0;z-index:0;opacity:.35; }
    .footer-bg img { width:100%;height:100%;object-fit:cover; }
    .footer > .container { position:relative;z-index:1; }
    .footer-grid { display:grid;grid-template-columns:2fr 1fr 1fr 1fr 1fr;gap:48px;padding-bottom:48px; }
    .footer-brand p { font-size:13px;color:rgba(255,255,255,.4);line-height:1.7;margin-top:14px;max-width:220px; }
    .footer-brand .nav-logo { color:#fff; }
    .footer-col-title { font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:rgba(255,255,255,.3);margin-bottom:16px; }
    .footer-col ul { list-style:none;display:flex;flex-direction:column;gap:10px; }
    .footer-col a { font-size:13px;color:rgba(255,255,255,.5);transition:color .15s; }
    .footer-col a:hover { color:#fff; }
    .footer-bottom { border-top:1px solid rgba(255,255,255,.07);padding:24px 0;display:flex;align-items:center;justify-content:space-between; }
    .footer-bottom-text { font-size:12px;color:rgba(255,255,255,.25); }
    .footer-socials { display:flex;gap:8px; }
    .footer-social { width:32px;height:32px;border-radius:8px;background:rgba(255,255,255,.06);display:flex;align-items:center;justify-content:center;font-size:12px;cursor:pointer;transition:background .15s; }
    .footer-social:hover { background:rgba(255,255,255,.12); }

    /* ── Info + Cards section ── */
    .contact-details-section { padding:100px 0; background:var(--bg); }
    .contact-details-grid {
      display:grid; grid-template-columns:1fr 1fr 1fr; gap:20px; align-items:stretch;
    }
    .contact-detail-card {
      background:var(--white); border:1px solid var(--border);
      border-radius:var(--radius-lg); padding:28px;
      display:flex; flex-direction:column; gap:12px;
      transition:box-shadow .2s, transform .2s;
    }
    .contact-detail-card:hover { box-shadow:var(--shadow-md); transform:translateY(-3px); }
    .contact-detail-icon {
      width:40px; height:40px; border-radius:var(--radius-sm);
      background:var(--accent-dim);
      display:flex; align-items:center; justify-content:center; font-size:18px;
    }
    .contact-detail-label {
      font-size:10px; font-weight:700; letter-spacing:.1em; text-transform:uppercase;
      color:var(--muted-2);
    }
    .contact-detail-value {
      font-size:13.5px; color:var(--text); line-height:1.75;
    }
    .contact-detail-value a { color:var(--text); transition:color .15s; }
    .contact-detail-value a:hover { color:var(--accent); }
    .contact-detail-socials { display:flex; gap:8px; }
    .contact-detail-social {
      width:32px; height:32px; border-radius:8px;
      background:var(--bg); border:1px solid var(--border-2);
      display:flex; align-items:center; justify-content:center;
      font-size:12px; cursor:pointer; transition:all .15s;
      color:var(--text); text-decoration:none;
    }
    .contact-detail-social:hover { background:var(--dark);color:#fff;border-color:var(--dark);transform:translateY(-2px); }

    /* ── FAQ (same as pricing) ── */
    .faq-header-row { display:flex;align-items:flex-start;justify-content:space-between;gap:40px;margin-bottom:48px; }
    .faq-header-left { max-width:700px; }
    .faq-header-left h2 { font-size:clamp(26px,3vw,38px);font-weight:800;letter-spacing:-.03em;color:var(--text);line-height:1.15;margin-bottom:12px; }
    .faq-header-left p { font-size:14px;color:var(--muted);line-height:1.7;white-space:nowrap; }
    .faq-view-all { flex-shrink:0;padding:10px 22px;border-radius:var(--radius-full);font-size:13px;font-weight:600;color:var(--text);border:1.5px solid var(--border-2);background:var(--white);cursor:pointer;transition:all .2s;white-space:nowrap;text-decoration:none; }
    .faq-view-all:hover { background:var(--bg);border-color:rgba(0,0,0,.15); }
    .faq-cols { display:grid;grid-template-columns:1fr 1fr;gap:0 48px; }
    .faq-item { border-bottom:1px solid var(--border-2);overflow:hidden; }
    .faq-item:first-child { border-top:1px solid var(--border-2); }
    .faq-q { display:flex;align-items:center;justify-content:space-between;gap:16px;padding:18px 0;cursor:pointer;font-size:14px;font-weight:600;color:var(--text);letter-spacing:-.01em;user-select:none; }
    .faq-icon { width:26px;height:26px;border-radius:50%;background:var(--bg);border:1.5px solid var(--border-2);display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:14px;font-weight:400;color:var(--muted);transition:all .2s;line-height:1; }
    .faq-item.open .faq-icon { background:var(--dark);border-color:var(--dark);color:#fff; }
    .faq-a { font-size:13.5px;color:var(--muted);line-height:1.75;max-height:0;overflow:hidden;transition:max-height .3s ease,padding .3s ease;padding:0; }
    .faq-item.open .faq-a { max-height:160px;padding-bottom:18px; }

    @media(max-width:1024px) { .contact-grid { grid-template-columns:1fr; } .contact-details-grid { grid-template-columns:1fr 1fr; } .faq-cols { grid-template-columns:1fr; } }
    @media(max-width:768px) {
      .contact-hero { padding:100px 0 60px; }
      .contact-hero-bg { opacity:0.35; }
      .contact-hero h1 { font-size:36px; }
      .contact-hero p { font-size:15px; }
      .navbar { padding:0 20px; } .nav-links { display:none; }
      .container { padding:0 20px; }
      .form-row { grid-template-columns:1fr; }
      .contact-details-grid { grid-template-columns:1fr; }
      .footer-grid { grid-template-columns:1fr; }
    }

/* ─── WATERCOLOR REVEAL ─── */
#wc-overlay {
  position: fixed;
  inset: 0;
  z-index: 99999;
  pointer-events: none;
}
#wc-canvas {
  display: block;
  width: 100%;
  height: 100%;
  filter: url(#wc-ink);
}

    /* ─── TESTIMONIALS ─── */
    .testimonials-section { background: var(--bg); overflow: hidden; position: relative; padding-top: 100px; padding-bottom:0 !important; }
    .testimonials-section .testi-bg { position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center top;z-index:0; }
