(function() {
  var wrap = document.getElementById('ms-tools');
  var field = document.getElementById('ms-field');
  var inner = document.getElementById('ms-chips-inner');
  var placeholder = document.getElementById('ms-placeholder');
  var hidden = document.getElementById('ms-hidden');
  var options = document.querySelectorAll('#ms-dropdown .ms-option');
  var selected = [];

  function renderChips() {
    var chips = inner.querySelectorAll('.ms-chip');
    chips.forEach(function(c) { c.remove(); });
    if (selected.length === 0) {
      placeholder.style.display = '';
    } else {
      placeholder.style.display = 'none';
      selected.forEach(function(val) {
        var chip = document.createElement('span');
        chip.className = 'ms-chip';
        chip.innerHTML = val + '<span class="ms-chip-x" data-val="' + val + '">×</span>';
        chip.querySelector('.ms-chip-x').addEventListener('click', function(e) {
          e.stopPropagation();
          deselect(this.getAttribute('data-val'));
        });
        inner.insertBefore(chip, placeholder);
      });
    }
    hidden.value = selected.join(', ');
  }

  function deselect(val) {
    selected = selected.filter(function(v) { return v !== val; });
    document.querySelectorAll('#ms-dropdown .ms-option').forEach(function(opt) {
      if (opt.getAttribute('data-value') === val) opt.classList.remove('selected');
    });
    renderChips();
  }

  var dragStartX = 0, dragScrollLeft = 0, didDrag = false;
  field.addEventListener('mousedown', function(e) {
    didDrag = false;
    dragStartX = e.pageX;
    dragScrollLeft = inner.scrollLeft;
  });
  field.addEventListener('mousemove', function(e) {
    if (e.buttons !== 1) return;
    var dx = e.pageX - dragStartX;
    if (Math.abs(dx) > 4) {
      didDrag = true;
      inner.scrollLeft = dragScrollLeft - dx;
    }
  });
  field.addEventListener('click', function() {
    if (didDrag) { didDrag = false; return; }
    wrap.classList.toggle('open');
    field.classList.toggle('open');
  });

  options.forEach(function(opt) {
    opt.addEventListener('click', function(e) {
      e.stopPropagation();
      var val = opt.getAttribute('data-value');
      if (opt.classList.contains('selected')) {
        deselect(val);
      } else {
        selected.push(val);
        opt.classList.add('selected');
        renderChips();
      }
    });
  });

  document.addEventListener('click', function(e) {
    if (!wrap.contains(e.target)) {
      wrap.classList.remove('open');
      field.classList.remove('open');
    }
  });
})();

function toggleFaq(el) {
    var item = el.parentElement;
    var icon = el.querySelector('.faq-icon');
    var isOpen = item.classList.contains('open');
    document.querySelectorAll('.faq-item').forEach(function(i) {
      i.classList.remove('open');
      i.querySelector('.faq-icon').textContent = '+';
    });
    if (!isOpen) {
      item.classList.add('open');
      icon.textContent = '−';
    }
  }

(function () {
  var overlay = document.getElementById('wc-overlay');
  var canvas  = document.getElementById('wc-canvas');
  var turb    = document.getElementById('wc-turb');

  if (turb) turb.setAttribute('seed', Math.floor(Math.random() * 120) + 1);

  var ctx = canvas.getContext('2d');
  var W, H;

  function resize() {
    W = canvas.width  = window.innerWidth;
    H = canvas.height = window.innerHeight;
  }
  resize();
  window.addEventListener('resize', resize);

  function easeOut(t) { return 1 - Math.pow(1 - t, 1.8); }

  function maxCornerDist(ox, oy) {
    return Math.max(
      Math.hypot(ox, oy),
      Math.hypot(W - ox, oy),
      Math.hypot(ox, H - oy),
      Math.hypot(W - ox, H - oy)
    );
  }

  var drops = [
    { fx: 0.22, fy: 0.20, reach: 1.35, lag: 0.00 },
    { fx: 0.78, fy: 0.32, reach: 1.30, lag: 0.06 },
    { fx: 0.48, fy: 0.78, reach: 1.25, lag: 0.10 }
  ];

  var DURATION  = 3400;
  var startTime = null;

  function frame(ts) {
    if (!startTime) startTime = ts;
    var progress = Math.min((ts - startTime) / DURATION, 1);

    ctx.globalCompositeOperation = 'source-over';
    ctx.globalAlpha = 1;
    ctx.fillStyle   = '#F7F7F4';
    ctx.fillRect(0, 0, W, H);

    ctx.globalCompositeOperation = 'destination-out';

    drops.forEach(function (d) {
      var t  = Math.max(0, Math.min((progress - d.lag) / (1 - d.lag), 1));
      var e  = easeOut(t);
      var ox = d.fx * W;
      var oy = d.fy * H;
      var r  = e * maxCornerDist(ox, oy) * d.reach;
      if (r < 1) return;

      var g = ctx.createRadialGradient(ox, oy, r * 0.30, ox, oy, r);
      g.addColorStop(0.00, 'rgba(0,0,0,1)');
      g.addColorStop(0.50, 'rgba(0,0,0,0.98)');
      g.addColorStop(0.70, 'rgba(0,0,0,0.85)');
      g.addColorStop(0.82, 'rgba(0,0,0,0.55)');
      g.addColorStop(0.92, 'rgba(0,0,0,0.20)');
      g.addColorStop(1.00, 'rgba(0,0,0,0)');

      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(ox, oy, r, 0, Math.PI * 2);
      ctx.fill();
    });

    ctx.globalCompositeOperation = 'source-over';
    ctx.globalAlpha = 1;

    if (progress < 1) {
      requestAnimationFrame(frame);
    } else {
      overlay.style.transition = 'opacity 0.45s ease';
      overlay.style.opacity    = '0';
      setTimeout(function () { overlay.remove(); }, 550);
    }
  }

  requestAnimationFrame(frame);
})();

(function () {
  var btn = document.getElementById('cf-submit');
  if (!btn) return;

  btn.addEventListener('click', async function (e) {
    e.preventDefault();

    var name    = (document.getElementById('cf-name')    || {}).value || '';
    var email   = (document.getElementById('cf-email')   || {}).value || '';
    var phone   = (document.getElementById('cf-phone')   || {}).value || '';
    var message = (document.getElementById('cf-message') || {}).value || '';
    var chips   = document.querySelectorAll('#ms-chips-inner .ms-chip');
    var tools   = Array.from(chips).map(function(c){ return c.dataset.value; });

    // Validation
    var errors = [];
    if (!name.trim())        errors.push('Name is required.');
    if (!email.trim())       errors.push('Email is required.');
    if (!tools.length)       errors.push('Please select at least one tool.');

    if (errors.length) {
      alert(errors.join('\n'));
      return;
    }

    btn.disabled = true;
    btn.textContent = 'Sending…';

    try {
      var res = await fetch('https://script.google.com/macros/s/AKfycbx7ZiEH7IQKSnpGH3BTXYnxJ7OMngF_yzexSXD1g1x8xOJioMpdt62_KhyL8eoQlWFdaA/exec', {
        method: 'POST',
        // text/plain keeps this a "simple" CORS request — no preflight
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ name: name, email: email, phone: phone, tools: tools, message: message, submittedAt: new Date().toISOString() })
      });
      var resOk = res.ok;
      try {
        var data = await res.json();
        if (data && data.success === false) resOk = false;
      } catch (_) { /* ignore parse errors */ }

      var card = btn.closest('.contact-form-card');
      if (resOk) {
        // Show success message
        card.innerHTML = `
          <div style="text-align:center;padding:48px 24px;">
            <div style="font-size:48px;margin-bottom:16px;">✅</div>
            <div style="font-size:22px;font-weight:800;letter-spacing:-0.02em;margin-bottom:10px;">Message sent!</div>
            <p style="font-size:15px;color:#6B7280;line-height:1.7;max-width:360px;margin:0 auto;">
              Thanks <strong>${name}</strong>, we've received your message and will get back to you within 24 hours.
            </p>
            <a href="/" style="display:inline-block;margin-top:24px;padding:12px 28px;background:#0D1117;color:#fff;border-radius:9999px;font-size:14px;font-weight:600;text-decoration:none;">← Back to Home</a>
          </div>
        `;
      } else {
        btn.disabled = false;
        btn.textContent = 'Send a message →';
        alert('Something went wrong. Please try again.');
      }
    } catch(err) {
      btn.disabled = false;
      btn.textContent = 'Send a message →';
      alert('Something went wrong. Please try again.');
    }
  });
})()
